WITH catalog_agg AS (SELECT cr.cr_reason_sk, SUM(cr.cr_return_amount) AS total_catalog_return_amt, MAX(cp.cp_department) AS cp_department FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk GROUP BY cr.cr_reason_sk), store_agg AS (SELECT sr.sr_reason_sk, SUM(sr.sr_return_amt) AS total_store_return_amt FROM store_returns sr GROUP BY sr.sr_reason_sk), combined AS (SELECT r.r_reason_desc, ca.total_catalog_return_amt, ca.cp_department, sa.total_store_return_amt, CASE WHEN sa.total_store_return_amt = 0 OR sa.total_store_return_amt IS NULL THEN NULL ELSE ca.total_catalog_return_amt / sa.total_store_return_amt END AS return_ratio FROM reason r LEFT JOIN catalog_agg ca ON r.r_reason_sk = ca.cr_reason_sk LEFT JOIN store_agg sa ON r.r_reason_sk = sa.sr_reason_sk) SELECT c.r_reason_desc, c.cp_department, c.total_catalog_return_amt, c.total_store_return_amt, c.return_ratio, CASE WHEN c.return_ratio > 2 THEN 'High Ratio' ELSE 'Normal' END AS ratio_category, RANK() OVER (ORDER BY c.return_ratio DESC NULLS LAST) AS ratio_rank FROM combined c WHERE c.return_ratio IS NOT NULL ORDER BY ratio_rank LIMIT 15
